'use strict';
// Synthetic recovery requests live only in this tab. No backend, authentication or execution.
const emergencyScopes={connection:['Подключение Orion · Limitless','Orion connection · Limitless'],global:['Общая аварийная остановка','Global emergency stop'],technical:['Технический режим','Technical mode']};
const emergencyStatuses={draft:['Нужна проверка','Check required'],waiting:['Ожидает второго сотрудника','Awaiting another employee'],approved:['Два подтверждения получены','Two approvals received'],unknown:['Результат применения неизвестен','Application outcome unknown'],applied:['Снятие ограничения подтверждено','Restriction removal confirmed'],rejected:['Отклонено','Rejected']};
function newEmergency(){return{scope:'connection',version:1,evidence:'missing',status:'draft',reason:'',approvals:[],events:[],proof:null,notice:null,revoked:false,handoff:false,returnRoute:'incidents',outcome:'success'};}
let emergency=newEmergency();
const emergencyAccess=()=>({read:!!account?.logged&&['ownerA','ownerB','lead','ops','audit'].includes(state.role),confirm:!!account?.logged&&['ownerA','ownerB'].includes(state.role)&&!(emergency.revoked&&state.role==='ownerA')});
const eb=(ru,en,a,extra='',primary=false)=>`<button type="button" class="btn${primary?' primary':''}" data-emergency="${a}" ${extra}>${pl(ru,en)}</button>`;
const emergencyDigest=()=>JSON.stringify([emergency.scope,emergency.version,emergency.evidence,emergency.reason]);
const emergencyReady=()=>emergency.evidence==='ready'&&emergency.reason.trim().length>=8;
function emergencyValid(){return emergency.approvals.filter(a=>a.digest===emergencyDigest()&&!(emergency.revoked&&a.id==='STAFF-201'));}
function emergencyLog(ru,en){emergency.events.push({actor:actor().id,version:emergency.version,label:[ru,en]});}
function emergencyInvalidate(){emergency.version++;emergency.approvals=[];emergency.proof=null;emergency.status='draft';}
function emergencyChange(key,value){if(!emergencyAccess().confirm||['unknown','applied'].includes(emergency.status))return false;if(key==='scope'&&emergencyScopes[value]){emergency.scope=value;emergency.evidence='missing';}else if(key==='reason')emergency.reason=String(value).slice(0,1000);else return false;emergencyInvalidate();return true;}
function emergencyApprove(){if(!emergencyAccess().confirm||!emergencyReady()||!['draft','waiting'].includes(emergency.status)||emergency.proof!==emergencyDigest()||emergencyValid().some(a=>a.id===actor().id))return false;emergency.approvals=emergencyValid();emergency.approvals.push({id:actor().id,owner:actor().owner,digest:emergencyDigest()});emergency.proof=null;emergency.status=emergency.approvals.length>=2&&emergency.approvals.some(a=>a.owner)?'approved':'waiting';emergencyLog('Подтверждена точная версия восстановления','Approved this exact recovery version');return true;}
function emergencyAction(a){if(!emergencyAccess().read)return false;const x=emergency,w=emergencyAccess().confirm;x.notice=null;
 if(a==='open'){x.returnRoute=state.route==='emergency'?x.returnRoute:state.route;navigate('emergency');return true;}
 if(a==='back'){navigate(x.returnRoute==='emergency'?'incidents':x.returnRoute);return true;}
 if(a==='incident'){incidents.id='INC-102';navigate('incident');return true;}
 if(a==='handoff'){x.handoff=true;x.proof=null;account.logged=false;navigate('entry');return true;}
 if(!w)return false;
 if(a==='evidence'&&!['unknown','applied'].includes(x.status)){emergencyInvalidate();x.evidence='ready';emergencyLog('Получен новый учебный пакет проверок','Loaded a new synthetic evidence package');}
 else if(a==='stale'&&!['unknown','applied'].includes(x.status)){emergencyInvalidate();x.evidence='stale';emergencyLog('Данные изменились; подтверждения сброшены','Evidence changed; approvals invalidated');}
 else if(a==='revoke'&&!['unknown','applied'].includes(x.status)){emergencyInvalidate();x.revoked=true;emergencyLog('Учебный отзыв полномочий STAFF-201','Synthetic permission revocation for STAFF-201');}
 else if(a==='proof'&&emergencyReady()&&['draft','waiting'].includes(x.status)&&!emergencyValid().some(p=>p.id===actor().id)){x.proof=emergencyDigest();x.notice=['Учебная проверка физического ключа успешна. Подтвердите эту версию ниже.','Synthetic physical-key check passed. Approve this version below.'];}
 else if(a==='approve'){if(!emergencyApprove())return false;}
 else if(a==='reject'&&['draft','waiting','approved'].includes(x.status)){x.status='rejected';x.approvals=[];x.proof=null;emergencyLog('Запрос отклонён; ограничение остаётся','Request rejected; restriction remains');}
 else if(a==='apply'&&x.status==='approved'&&emergencyReady()&&emergencyValid().length===2&&emergencyValid().some(p=>p.owner)){
  if(x.outcome==='failure'){emergencyInvalidate();x.notice=['Применение не началось. Нужны новая проверка и два новых подтверждения.','Application did not start. Fresh checks and two new approvals are required.'];}
  else{x.status=x.outcome==='unknown'?'unknown':'applied';x.proof=null;}emergencyLog('Учебный результат применения: '+x.status,'Synthetic application outcome: '+x.status);
 }
 else if(a==='reconcile'&&x.status==='unknown'){x.status='applied';emergencyLog('Получено подтверждение исходного применения; повторной отправки нет','Original application confirmed; no resend');}
 else if(a==='restart'&&['applied','rejected'].includes(x.status)){emergency=newEmergency();}
 else return false;render();const title=document.querySelector('h1');title?.setAttribute('tabindex','-1');title?.focus({preventScroll:true});return true;
}
function emergencyPage(){if(!emergencyAccess().read)return heading(pl('Восстановление недоступно','Recovery unavailable'))+`<p>${pl('У текущего сотрудника нет доступа к этому разделу.','The current employee has no access to this section.')}</p>`;const x=emergency,w=emergencyAccess().confirm,valid=emergencyValid(),locked=['unknown','applied'].includes(x.status),signed=valid.some(p=>p.id===actor().id);return heading(pl('Аварийное восстановление','Emergency recovery'),pl('Снять одно ограничение после проверки причины. Торговля и переводы автоматически не запускаются.','Lift one restriction after checking its cause. Trading and transfers do not restart automatically.'),eb('Вернуться к работе','Back to work','back'))+`<div class="emergency-summary"><span class="badge ${x.status==='applied'?'good':'warn'}">${pl(...emergencyStatuses[x.status])}</span><span>RECOVERY-DEMO-01 · ${pl('версия','version')} ${x.version}</span></div>${x.notice?`<p class="support-notice" role="status">${pl(...x.notice)}</p>`:''}<div class="support-layout"><div><section class="panel"><h2>${pl('Что восстанавливаем','What we are restoring')}</h2>${feedbackSelect('emergency-scope',pl('Ограничение','Restriction'),Object.entries(emergencyScopes).map(([k,v])=>[k,pl(...v)]),x.scope,!w||locked)}<dl class="feedback-meta"><dt>${pl('Среда','Environment')}</dt><dd>Paper Alpha · ${pl('учебный сценарий','synthetic scenario')}</dd><dt>${pl('Область действия','Scope')}</dt><dd>${x.scope==='connection'?'U-DEMO-009 · S-DEMO-009 · Limitless':pl('Вся среда · Polymarket + Limitless','Entire environment · Polymarket + Limitless')}</dd><dt>${pl('Действие','Action')}</dt><dd>${pl('Снять только выбранное аварийное ограничение','Remove only the selected emergency restriction')}</dd></dl><label for="emergency-reason">${pl('Почему восстановление безопасно','Why recovery is safe')}</label><textarea id="emergency-reason" rows="3" maxlength="1000" ${!w||locked?'disabled':''}>${escape(x.reason)}</textarea><small>${pl('Укажите основание, минимум 8 символов. Изменение создаёт новую версию и сбрасывает подтверждения.','State the reason, at least 8 characters. Any change creates a new version and clears approvals.')}</small></section><section class="panel"><h2>${pl('Проверка перед восстановлением','Pre-recovery checks')}</h2><ul class="trading-checks">${[['Причина устранена; есть подтверждение','Cause resolved; evidence available'],['Состояние компонентов и данные проверены','Component state and data checked'],['Исходные операции сверены; повтор исключён','Original operations reconciled; replay prevented']].map(v=>`<li><strong>${x.evidence==='ready'?pl('Подтверждено','Confirmed'):pl('Не подтверждено','Not confirmed')}</strong><span>${pl(...v)}</span></li>`).join('')}</ul><p class="muted">${x.evidence==='ready'?`EVID-RECOVERY-DEMO-${x.version} · ${pl('учебный пакет этой версии','synthetic package for this version')}`:pl('Не хватает свежих подтверждений. Сначала получите результаты проверки.','Fresh evidence is missing. Obtain check results first.')}</p>${w&&!locked?eb('Получить учебные результаты проверки','Load synthetic check results','evidence'):''}<details><summary>${pl('Что останется ограничено?','What stays restricted?')}</summary><p>${pl('Другие аварийные и адресные запреты остаются. Неизвестный результат другой операции требует своей сверки. Старые заявки не воспроизводятся. Неотправленные денежные действия требуют новой проверки и подтверждения первоначального инициатора.','Other emergency and targeted restrictions remain. An unknown outcome of another operation needs its own reconciliation. Old requests are not replayed. Unsent money actions require fresh checks and approval from their original initiator.')}</p>${x.scope==='technical'?`<p>${pl('Пока технический режим включён, приложение, публичный API и продуктовые фоновые задания закрыты. Работают только аварийные функции. Сверка ничего не отправляет. Уже отправленные операции могут завершиться.','While technical mode is on, the app, public API and product background tasks are closed. Only emergency functions remain. Reconciliation sends nothing. Already-submitted operations can complete.')}</p>`:''}</details></section></div><aside class="support-context"><section class="panel"><h2>${pl('Два независимых подтверждения','Two independent approvals')}</h2><p>${pl('Нужны владелец и другой уполномоченный сотрудник. В этом учебном наборе право подтверждать выдано только двум владельцам.','An owner and another authorized employee are required. In this synthetic assignment, only the two owners have approval permission.')}</p><ol class="emergency-approvals">${[0,1].map(i=>`<li>${valid[i]?`${valid[i].id} · ${pl('подтверждено','approved')} · v${x.version}`:pl('Ожидает подтверждения','Awaiting approval')}</li>`).join('')}</ol>${!w?`<p class="support-notice">${pl('Только просмотр: право подтверждать не выдано или отозвано.','Read only: approval permission is not assigned or was revoked.')}</p>`:''}${w&&['draft','waiting'].includes(x.status)?signed?`<p>${pl('Вы уже подтвердили эту версию. Нужен другой сотрудник.','You have already approved this version. Another employee is required.')}</p>`:`<p>${pl('Перед каждым подтверждением заново проверьте личность физическим ключом. Настоящий ключ в прототипе не запрашивается.','Verify your identity again with a physical key before each approval. This prototype never requests a real key.')}</p>${eb('Проверить личность · учебный пример','Verify identity · synthetic example','proof',!emergencyReady()?'disabled':'')}${eb('Подтвердить эту версию','Approve this version','approve',x.proof!==emergencyDigest()?'disabled':'',true)}`:''}${['waiting','approved'].includes(x.status)?eb('Выйти и открыть другой учебный вход','Sign out and open another test sign-in','handoff'):''}${w&&x.status==='approved'?eb('Применить согласованное восстановление','Apply approved recovery','apply','',true):''}${w&&['draft','waiting','approved'].includes(x.status)?eb('Отклонить запрос','Reject request','reject'):''}${x.status==='unknown'?`<p class="support-notice">${pl('Повторное применение заблокировано. Проверяйте исходный запрос; ограничение пока считается действующим.','Reapplication is blocked. Check the original request; the restriction is still treated as active.')}</p>${w?eb('Сверить исходный результат · пример','Reconcile original outcome · example','reconcile'):''}`:''}${x.status==='applied'?`<p class="support-notice">${pl('Подтверждено снятие выбранного ограничения. Это не разрешение сделки или выплаты. Другие запреты сохранены.','Removal of the selected restriction is confirmed. This is not a trade or payout authorization. Other restrictions remain.')}</p>`:''}${w&&['applied','rejected'].includes(x.status)?eb('Начать новый учебный пример','Start a new test example','restart'):''}</section><section class="panel"><h2>${pl('Связанный разбор','Related investigation')}</h2>${eb('Инцидент INC-102','Incident INC-102','incident')}<p class="muted">${pl('Альтернативный учебный сценарий. Исходный инцидент и торговые снимки не перезаписываются.','Alternative synthetic scenario. The original incident and trading snapshots are not overwritten.')}</p></section></aside></div><details class="panel"><summary>${pl('История подтверждений','Approval history')} · ${x.events.length}</summary>${x.events.map(e=>`<p>${e.actor} · v${e.version} · ${escape(pl(...e.label))}</p>`).join('')||pl('Действий ещё нет.','No actions yet.')}</details>${w&&!locked?`<details class="panel"><summary>${pl('Учебные проверки ошибок','Synthetic failure checks')}</summary><div class="actions">${eb('Данные изменились','Evidence changed','stale')}${eb('Отозвать право STAFF-201 · пример','Revoke STAFF-201 permission · example','revoke')}</div>${feedbackSelect('emergency-outcome',pl('Результат следующего применения','Next application outcome'),[['success',pl('Подтверждено','Confirmed')],['unknown',pl('Результат неизвестен','Unknown outcome')],['failure',pl('Не началось','Did not start')]],x.outcome)}</details>`:''}`;}
document.addEventListener('click',e=>{const el=e.target.closest('[data-emergency]');if(el&&!el.disabled)emergencyAction(el.dataset.emergency);});
document.addEventListener('change',e=>{if(e.target.id==='emergency-scope'){emergencyChange('scope',e.target.value);render();document.querySelector('#emergency-scope')?.focus();}if(e.target.id==='emergency-outcome'&&emergencyAccess().confirm)emergency.outcome=e.target.value;});
document.addEventListener('input',e=>{if(e.target.id==='emergency-reason'){const pos=e.target.selectionStart;emergencyChange('reason',e.target.value);render();const n=document.querySelector('#emergency-reason');n?.focus();n?.setSelectionRange(pos,pos);}});
